/// <summary>
/// CB705_Rebate batch jobs & Vendor payback extension. Create instance of context object
/// </summary>
/// <param name = "_contract">_contract</param>
public void process(TAMRebatePostContract _contract)
{
    using (METSkipPostingContext_BEC context = METSkipPostingContext_BEC::construct())
    {
        context.isCalledFromRebateBatch = _contract.parmIsCalledFromMainBatchJob();
        next process(_contract);
    }
}
